CREATE TABLE admins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL);
CREATE TABLE sessions(token_hash text PRIMARY KEY,admin_id uuid REFERENCES admins ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts(key text PRIMARY KEY,attempts int NOT NULL DEFAULT 0,window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),external_id text UNIQUE NOT NULL,name text NOT NULL,url text NOT NULL,approved boolean NOT NULL DEFAULT false,publication_confirmed boolean NOT NULL DEFAULT false,last_success_at timestamptz,next_run_at timestamptz NOT NULL DEFAULT now(),last_error text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(NOT approved OR publication_confirmed));
CREATE TABLE listings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),fingerprint text,title text NOT NULL,body text NOT NULL,kind text CHECK(kind IN ('rent','sale')),city text,neighborhood text,price bigint,rooms numeric,area numeric,amenities jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'review' CHECK(status IN ('published','review','hidden','expired')),overrides jsonb NOT NULL DEFAULT '{}',published_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX listings_search ON listings(status,city,kind,published_at DESC);
CREATE INDEX listings_fingerprint ON listings(fingerprint);
CREATE TABLE posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid NOT NULL REFERENCES sources ON DELETE CASCADE,external_id text NOT NULL UNIQUE,url text NOT NULL,body text NOT NULL,body_hash text NOT NULL,published_at timestamptz NOT NULL,collected_at timestamptz NOT NULL DEFAULT now(),listing_id uuid REFERENCES listings ON DELETE SET NULL);
CREATE TABLE images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES listings ON DELETE CASCADE,filename text UNIQUE NOT NULL,mime text NOT NULL,position int NOT NULL DEFAULT 0);
CREATE TABLE quarantine(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid REFERENCES sources ON DELETE CASCADE,reason text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('discover','sync','recover')),source_id uuid REFERENCES sources ON DELETE CASCADE,status text NOT NULL DEFAULT 'queued',attempts int NOT NULL DEFAULT 0,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,error text);
CREATE UNIQUE INDEX jobs_pending ON jobs(kind,COALESCE(source_id,'00000000-0000-0000-0000-000000000000'::uuid)) WHERE status IN ('queued','running');
CREATE TABLE crawler_state(id int PRIMARY KEY CHECK(id=1),status text NOT NULL DEFAULT 'starting',message text,heartbeat timestamptz NOT NULL DEFAULT now(),recovery_until timestamptz);
INSERT INTO crawler_state(id) VALUES(1);
CREATE TABLE removal_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid REFERENCES listings ON DELETE SET NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
